"""union_run_v3.py -- turn 134 driver. One cell, or a sweep, for the STOPPING-RULE
comparison. Built on the turn-129/132 machinery, unchanged:

  * `build_model` is IMPORTED from union_run_v2 (the frozen instance builder);
  * the agent is `union_agent_v3.make_agent`, generated by make_agent_v3.py from
    the frozen `union_agent_v2.py` by four mechanical substitutions;
  * the candidate list is produced by the frozen `candidate_gen.py`, so the ONLY
    thing that differs between arms in this file is the stopping rule.

The transplant control: arm "frozen_rule" dispatches to stopping_rules._frozen,
which DELEGATES to arbitration_scaled.plan -- the very rule the frozen arms used.
`frozen_rule` must therefore reproduce arm "union" byte-for-byte; check_v3.py
asserts that before any comparison is reported.

  python3 union_run_v3.py cell  <arm> <inst> <param> <seed> [T]
  python3 union_run_v3.py sweep <arm> <inst> <param> <nsim> <out.json> [T]
"""
import json
import os
import sys
import time

import numpy as np

_HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(_HERE, "ext", "latt_py3"))
sys.path.insert(0, _HERE)

from union_run_v2 import build_model          # frozen instance builder
from union_agent_v3 import make_agent          # the generated agent

V3_KINDS = ("voi", "voi_rate", "voi_rate_noexp", "conf", "conf_noexp",
            "frozen_rule", "union", "union_noexp", "union_nocost", "pure",
            "beta0")


def run_cell(arm, inst, param, seed, T=400):
    np.random.seed(seed)
    model = build_model(inst, param)
    t0 = time.time()
    ag = make_agent(arm if arm in V3_KINDS else arm, seed)
    r = ag.run(T, model)
    d = ag.diagnostics()
    d["policy"] = dict(getattr(ag, "policy", {}))
    d["rule_name"] = getattr(ag, "rule_name", None)
    out = {"arm": arm, "inst": inst, "param": param, "seed": seed, "T": T,
           "regret": float(r), "seconds": round(time.time() - t0, 4),
           "optimal": float(model.optimal)}
    out.update(d)
    for k, v in list(out.items()):
        if isinstance(v, dict):
            out[k] = {kk: (int(vv) if hasattr(vv, "item") else vv)
                      for kk, vv in v.items()}
        elif hasattr(v, "item"):
            out[k] = v.item()
    return out


def sweep(arm, inst, param, nsim, T=400, seed0=1):
    rows = [run_cell(arm, inst, param, seed0 + i, T) for i in range(nsim)]
    regs = [r["regret"] for r in rows]
    return {"arm": arm, "inst": inst, "param": param, "nsim": nsim, "T": T,
            "seed0": seed0, "mean_regret": float(np.mean(regs)),
            "sem_regret": float(np.std(regs, ddof=1) / np.sqrt(len(regs))),
            "sd_regret": float(np.std(regs, ddof=1)),
            "frac_optimal": float(np.mean([r.get("chosen_is_optimal", 0)
                                           for r in rows])),
            "mean_probes": float(np.mean([r.get("n_probes", 0) for r in rows])),
            "mean_explore": float(np.mean([r.get("n_explore_picks", 0)
                                           for r in rows])),
            "mean_active": float(np.mean([r.get("active_pulls", 0) for r in rows])),
            "rows": rows}


if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "cell":
        print(json.dumps(run_cell(sys.argv[2], sys.argv[3], sys.argv[4],
                                  int(sys.argv[5]),
                                  int(sys.argv[6]) if len(sys.argv) > 6 else 400)))
    elif mode == "sweep":
        arm, inst, param, nsim, out = (sys.argv[2], sys.argv[3], sys.argv[4],
                                       int(sys.argv[5]), sys.argv[6])
        T = int(sys.argv[7]) if len(sys.argv) > 7 else 400
        res = sweep(arm, inst, param, nsim, T)
        with open(out, "w") as f:
            json.dump(res, f, indent=1)
        print(json.dumps({k: v for k, v in res.items() if k != "rows"}))
